 "content": "def transform(grid):
    h,w=len(grid),len(grid[0])
    # Move each nonzero object into a diagonal staircase, preserving cell offsets.
    # Order objects by their input position, top-to-bottom then left-to-right.
    seen=set(); objs=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if not color or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            objs.append((min(cells),color,cells))
    objs.sort()
    out=[[0]*w for _ in range(h)]
    for i,(_,color,cells) in enumerate(objs):
        r0=min(r for r,c in cells); c0=min(c for r,c in cells)
        # staircase spacing one row and one column per object
        dr=i-r0; dc=i-c0
        for r,c in cells:
            rr,cc=r+dr,c+dc
            if 0<=rr<h and 0<=cc<w: out[rr][cc]=color
    return out
