    r0 = c0 = 0
    for i, (_, color, shape) in enumerate(objs):
        for dr, dc in shape:
            r, c = r0 + dr, c0 + dc
            if 0 <= r < h and 0 <= c < w:
                out[r][c] = color
        if i + 1 < len(objs):
            r0 += max(dr for dr, dc in shape)
            c0 += max(dc for dr, dc in shape)
    return out
